    tiprack_300 = protocol.load_labware(
        load_name="opentrons_96_tiprack_300ul",
        location="4",
        label="300 µL tip rack",
    )

    # Reset any persistent offset from previous runs, then apply desired offset
    tiprack_300.set_offset(x=0, y=0, z=0)
    offset_mm = (4 - 1) * 9.0  # 27mm right shift
    tiprack_300.set_offset(x=offset_mm, y=0, z=0)


