        {"source": "C1", "wells": ["D8", "G3", "H7"], "label": "PAC-3310 at 0.000001 M"},
        {"source": "D1", "wells": ["B8", "C4", "D5"], "label": "PAC-3310 at 1e-7 M"},
        {"source": "E1", "wells": ["B7", "G10"], "label": "PAC-3310 at 1e-8 M"},
        {"source": "G1", "wells": ["A5", "E10", "H3"], "label": "PAC-3310 at 1e-10 M"},
        {"source": "A1", "wells": ["G6", "H8", "C6"], "label": "Control (buffer from A1)"},
        {"source": "H1", "wells": ["F7", "B9", "A4"], "label": "PAC-3310 at 1e-11 M"},
        {"source": "F1", "wells": ["H10", "H5", "E8"], "label": "PAC-3310 at 1e-9 M"},
        {"source": "H1", "wells": ["D4", "B3", "E7"], "label": "PAC-3310 at 1e-11 M"},
        {"source": "H1", "wells": ["A9", "D10"], "label": "PAC-3310 at 1e-11 M"},
        {"source": "F1", "wells": ["F6", "E3"], "label": "PAC-3310 at 1e-9 M"},
        {"source": "C1", "wells": ["F8", "A10", "E9"], "label": "PAC-3310 at 0.000001 M"},
        {"source": "D1", "wells": ["C9", "B6"], "label": "PAC-3310 at 1e-7 M"},
        {"source": "A1", "wells": ["D7", "B5", "G5"], "label": "Control (buffer from A1)"},
        {"source": "B1", "wells": ["E5", "C5", "E4"], "label": "PAC-3310 at 0.00001 M"},
        {"source": "B1", "wells": ["H9", "A8", "B10"], "label": "PAC-3310 at 0.00001 M"},
        {"source": "C1", "wells": ["A6", "A7"], "label": "PAC-3310 at 0.000001 M"},
        {"source": "G1", "wells": ["B4", "F4", "F3"], "label": "PAC-3310 at 1e-10 M"}
