        p300.dispense(100 * len(wells), waste_wells[waste_idx % len(waste_wells)].top())
        p300.blow_out(waste_wells[waste_idx % len(waste_wells)].top())
        p300.blow_out(waste_wells[waste_idx % len(waste_wells)].top())
