    # Step 1: Transfer diluted samples only (mix, aspirate 20 µL)
    p300.pick_up_tip()


    transfers = [("B5", "A3"), ("C3", "B3"), ("C6", "C3"), ("D7", "D3"), ("G4", "E3"), ("G5", "F3"), ("G6", "G3"), ("H8", "H3"), ("A8", "A4"), ("B10", "B4"), ("C5", "C4"), ("D6", "D4"), ("E4", "E4"), ("E5", "F4"), ("G7", "G4"), ("H9", "H4"), ("A6", "A5"), ("A7", "B5"), ("A10", "C5"), ("D8", "D5"), ("E9", "E5"), ("F8", "F5"), ("G3", "G5"), ("H7", "H5"), ("B6", "A6"), ("B8", "B6"), ("C4", "C6"), ("C7", "D6"), ("C9", "E6"), ("D5", "F6"), ("F5", "G6"), ("G9", "H6"), ("A3", "A7"), ("B7", "B7"), ("C8", "C7"), ("C10", "D7"), ("D3", "E7"), ("E6", "F7"), ("F10", "G7"), ("G10", "H7"), ("D9", "A8"), ("E3", "B8"), ("E8", "C8"), ("F6", "D8"), ("F9", "E8"), ("G8", "F8"), ("H5", "G8"), ("H10", "H8"), ("A5", "A9"), ("B4", "B9"), ("E10", "C9"), ("F3", "D9"), ("F4", "E9"), ("H3", "F9"), ("H4", "G9"), ("H6", "H9"), ("A4", "A10"), ("A9", "B10"), ("B3", "C10"), ("B9", "D10"), ("D4", "E10"), ("D10", "F10"), ("E7", "G10"), ("F7", "H10")]
    for src, dst in transfers:
        p300.mix(3, 80, cell_plate.wells_by_name()[src].bottom(1))
        p300.aspirate(20, cell_plate.wells_by_name()[src].bottom(1))
        p300.dispense(20, dilution_plate.wells_by_name()[dst].bottom(2))
        p300.blow_out(dilution_plate.wells_by_name()[dst].top())
    p300.drop_tip()

    # Step 2: Add buffer to all diluted wells (80 µL to make 1:5 dilution)
    # Switch to 8-channel ALL mode for faster buffer addition
    p300.configure_nozzle_layout(style=ALL, start="A1", tip_racks=[tiprack_300])
    p300.pick_up_tip()


    for col in [3, 4, 5, 6, 7, 8, 9, 10]:
        p300.aspirate(80, buffer_reservoir.wells()[0].bottom(1))
        p300.dispense(80, dilution_plate.wells_by_name()[f"A{col}"].bottom(2))
        p300.blow_out(dilution_plate.wells_by_name()[f"A{col}"].top())
    p300.drop_tip()

    # Switch back to single-channel mode
    p300.configure_nozzle_layout(style=SINGLE, start="H1", tip_racks=[tiprack_300])

    protocol.comment("Lysate dilution complete: 64 samples processed (diluted only)")

    # ===== ELISA STANDARDS PREPARATION =====
    protocol.pause("Please place master ELISA standard in tube rack slot A1, and add 7250 µL of ELISA buffer to reservoir (slot 6), then click RESUME to continue.")
    protocol.comment("Preparing 8 ELISA standards via 1:3 serial dilution in deep well plate column 11")

    # Pre-fill all standard wells with 600 µL buffer using 8-channel ALL mode (2x 300 µL)
    p300.configure_nozzle_layout(style=ALL, start="A1", tip_racks=[tiprack_300])
    p300.pick_up_tip()

    # Add 600 µL in two 300 µL transfers
    p300.aspirate(300, buffer_reservoir.wells()[0].bottom(1))
    p300.dispense(300, dilution_plate.wells_by_name()["A11"].bottom(2))
    p300.blow_out(dilution_plate.wells_by_name()["A11"].top())

    p300.aspirate(300, buffer_reservoir.wells()[0].bottom(1))
    p300.dispense(300, dilution_plate.wells_by_name()["A11"].bottom(2))
    p300.blow_out(dilution_plate.wells_by_name()["A11"].top())

    p300.drop_tip()

    # Switch to single-channel mode to add remaining 300 µL to first well only
    p300.configure_nozzle_layout(style=SINGLE, start="H1", tip_racks=[tiprack_300])
    p300.pick_up_tip()

    # Add 300 µL to first well to reach 900 µL total
    p300.aspirate(300, buffer_reservoir.wells()[0].bottom(1))
    p300.dispense(300, dilution_plate.wells_by_name()["A11"].bottom(2))
    p300.blow_out(dilution_plate.wells_by_name()["A11"].top())

    p300.drop_tip()

    # Serial dilution: Add master standard and perform 1:3 dilutions
    p300.pick_up_tip()

    # Add 100 µL master standard to first well
    p300.aspirate(100, tuberack.wells_by_name()["A1"].bottom(2))
    p300.dispense(100, dilution_plate.wells_by_name()["A11"].bottom(2))
    p300.mix(3, 300, dilution_plate.wells_by_name()["A11"].bottom(2))
    p300.blow_out(dilution_plate.wells_by_name()["A11"].top())


    std_wells = ["A11", "B11", "C11", "D11", "E11", "F11", "G11", "H11"]
    for i in range(len(std_wells) - 1):
        p300.aspirate(300, dilution_plate.wells_by_name()[std_wells[i]].bottom(2))
        p300.dispense(300, dilution_plate.wells_by_name()[std_wells[i+1]].bottom(2))
        p300.mix(3, 300, dilution_plate.wells_by_name()[std_wells[i+1]].bottom(2))
        p300.blow_out(dilution_plate.wells_by_name()[std_wells[i+1]].top())
    p300.drop_tip()

    protocol.comment("ELISA standards preparation complete - 8 standards created via 1:3 dilution")

    # ===== ELISA PLATE SETUP =====
    # Load ELISA plate
    elisa_plate = protocol.load_labware('nest_96_wellplate_200ul_flat', 7)

    protocol.pause("Please place ELISA plate in slot 7, then click RESUME to continue.")
    protocol.comment("Setting up ELISA plate: standards in column 1, samples in remaining columns")

    # Prepare standards column (single-channel mode)
    # Use one tip for all buffer additions and standard transfers
    p300.pick_up_tip()

    # A1: 100 µL buffer (blank)
    p300.aspirate(100, buffer_reservoir.wells()[7].bottom(1))
    p300.dispense(100, elisa_plate.wells_by_name()["A1"].bottom(2))
    p300.blow_out(elisa_plate.wells_by_name()["A1"].top())

    # B1: 50 µL buffer
    p300.aspirate(50, buffer_reservoir.wells()[7].bottom(1))
    p300.dispense(50, elisa_plate.wells_by_name()["B1"].bottom(2))
    p300.blow_out(elisa_plate.wells_by_name()["B1"].top())

    # C1-H1: Transfer 50 µL from diluted standards (reverse order: 7→6→5→4→3→2)
    # Standard 7 (2nd most diluted) → C1, Standard 6 → D1, ..., Standard 2 → H1
    p300.aspirate(50, dilution_plate.wells_by_name()["G11"].bottom(2))
    p300.dispense(50, elisa_plate.wells_by_name()["C1"].bottom(2))
    p300.blow_out(elisa_plate.wells_by_name()["C1"].top())

    p300.aspirate(50, dilution_plate.wells_by_name()["F11"].bottom(2))
    p300.dispense(50, elisa_plate.wells_by_name()["D1"].bottom(2))
    p300.blow_out(elisa_plate.wells_by_name()["D1"].top())

    p300.aspirate(50, dilution_plate.wells_by_name()["E11"].bottom(2))
    p300.dispense(50, elisa_plate.wells_by_name()["E1"].bottom(2))
    p300.blow_out(elisa_plate.wells_by_name()["E1"].top())

    p300.aspirate(50, dilution_plate.wells_by_name()["D11"].bottom(2))
    p300.dispense(50, elisa_plate.wells_by_name()["F1"].bottom(2))
    p300.blow_out(elisa_plate.wells_by_name()["F1"].top())

    p300.aspirate(50, dilution_plate.wells_by_name()["C11"].bottom(2))
    p300.dispense(50, elisa_plate.wells_by_name()["G1"].bottom(2))
    p300.blow_out(elisa_plate.wells_by_name()["G1"].top())

    p300.aspirate(50, dilution_plate.wells_by_name()["B11"].bottom(2))
    p300.dispense(50, elisa_plate.wells_by_name()["H1"].bottom(2))
    p300.blow_out(elisa_plate.wells_by_name()["H1"].top())

    p300.drop_tip()

    protocol.comment("Standards column complete")

    # Switch to 8-channel ALL mode for sample transfer
    p300.configure_nozzle_layout(style=ALL, start="A1", tip_racks=[tiprack_300])

    # Transfer samples from diluted lysate block to ELISA plate (50 µL per well)
    # ELISA plate columns 2+ (offset by 1 due to standards in column 1)
    # Use same tips for all sample columns
    p300.pick_up_tip()

    for src_col, dst_col in [(3, 2), (4, 3), (5, 4), (6, 5), (7, 6), (8, 7), (9, 8), (10, 9)]:
        p300.mix(3, 50, dilution_plate.wells_by_name()[f"A{src_col}"].bottom(2))
        p300.aspirate(50, dilution_plate.wells_by_name()[f"A{src_col}"].bottom(2))
        p300.dispense(50, elisa_plate.wells_by_name()[f"A{dst_col}"].bottom(2))
        p300.blow_out(elisa_plate.wells_by_name()[f"A{dst_col}"].top())
    p300.drop_tip()

    protocol.comment("Sample transfer to ELISA plate complete")

    # ===== ELISA REAGENTS ADDITION =====
    # Load tracer and antiserum reservoirs (custom 8-well format)
    tracer_reservoir = protocol.load_labware_from_definition(custom_reservoir_def, 10, "ELISA tracer reservoir")
    antiserum_reservoir = protocol.load_labware_from_definition(custom_reservoir_def, 11, "ELISA antiserum reservoir")

    protocol.pause("Please add 5600 µL of ELISA tracer to reservoir (slot 10) and 5550 µL of ELISA antiserum to reservoir (slot 11), then click RESUME to continue.")

    protocol.comment("Adding ELISA tracer and antiserum to all wells")

    # Add tracer to ALL wells (standards + samples) - 50 µL per well, using 8-channel
    # Pick up fresh tips for tracer addition
    p300.pick_up_tip()

    for col in [1, 2, 3, 4, 5, 6, 7, 8, 9]:
        p300.aspirate(50, tracer_reservoir.wells()[0].bottom(1))
        p300.dispense(50, elisa_plate.wells_by_name()[f"A{col}"].bottom(2))
        p300.blow_out(elisa_plate.wells_by_name()[f"A{col}"].top())
    p300.drop_tip()

    protocol.comment("Tracer addition complete")

    # Add antiserum to sample wells only (columns 2+) - 50 µL per well, using 8-channel
    # Pick up fresh tips for antiserum addition
    p300.pick_up_tip()

    for col in [2, 3, 4, 5, 6, 7, 8, 9]:
        p300.aspirate(50, antiserum_reservoir.wells()[0].bottom(1))
        p300.dispense(50, elisa_plate.wells_by_name()[f"A{col}"].bottom(2))
        p300.blow_out(elisa_plate.wells_by_name()[f"A{col}"].top())
    p300.drop_tip()

    protocol.comment("Antiserum addition to samples complete")

    # Add antiserum to standards (B1-H1 only, skip A1)
    # Switch back to single-channel mode
    p300.configure_nozzle_layout(style=SINGLE, start="H1", tip_racks=[tiprack_300])

    # Use single tip for all standard wells
    p300.pick_up_tip()

    for row in ["B", "C", "D", "E", "F", "G", "H"]:
        p300.aspirate(50, antiserum_reservoir.wells()[7].bottom(1))
        p300.dispense(50, elisa_plate.wells_by_name()[f"{row}1"].bottom(2))
        p300.blow_out(elisa_plate.wells_by_name()[f"{row}1"].top())

    p300.drop_tip()

    protocol.comment("Antiserum addition to standards complete")
    protocol.comment("ELISA plate preparation complete - ready for incubation")

    protocol.comment("Protocol complete!")
